from dataclasses import dataclass
from datetime import datetime
from decimal import Decimal
from typing import Optional


@dataclass(frozen=True)
class Promotion:
    code: str
    percent_off: Decimal
    expires_at: datetime


@dataclass(frozen=True)
class CheckoutResult:
    status: str  # "ok" or "needs_confirmation"
    total: Decimal
    message: str = ""


def price_order(subtotal: Decimal, promo: Optional[Promotion], now: datetime,
                confirmed_without_promo: bool = False) -> CheckoutResult:
    """An expired promotion is never applied silently and never blocks the order:
    the customer must confirm paying the full price before checkout proceeds."""
    if promo is None:
        return CheckoutResult("ok", subtotal)
    if now < promo.expires_at:
        discount = subtotal * promo.percent_off / 100
        return CheckoutResult("ok", subtotal - discount)
    if confirmed_without_promo:
        return CheckoutResult("ok", subtotal)
    return CheckoutResult(
        "needs_confirmation", subtotal,
        f"Promotion {promo.code} has expired. Continue at full price?")
