import unittest
from datetime import datetime, timedelta
from decimal import Decimal as D
from checkout import Promotion, price_order

NOW = datetime(2026, 1, 1, 12)
def promo(delta): return Promotion("SAVE10", D(10), NOW + delta)

class T(unittest.TestCase):
    def test_no_promo(self):
        self.assertEqual(price_order(D(100), None, NOW).total, D(100))
    def test_valid_promo_applies(self):
        r = price_order(D(100), promo(timedelta(days=1)), NOW)
        self.assertEqual((r.status, r.total), ("ok", D(90)))
    def test_expired_requires_confirmation(self):
        r = price_order(D(100), promo(-timedelta(days=1)), NOW)
        self.assertEqual((r.status, r.total), ("needs_confirmation", D(100)))
        self.assertIn("SAVE10", r.message)
    def test_expired_confirmed_charges_full_price(self):
        r = price_order(D(100), promo(-timedelta(days=1)), NOW, True)
        self.assertEqual((r.status, r.total), ("ok", D(100)))
    def test_expiry_instant_counts_as_expired(self):
        self.assertEqual(price_order(D(100), promo(timedelta(0)), NOW).status, "needs_confirmation")

unittest.main() if __name__ == "__main__" else None
E
